Ltac clipnorm1 := first [
    match goal with |- context [Z.land ((bv_signed (Z_to_bv 64 ?x) / 9223372036854775808) mod 18446744073709551616) (?x mod 18446744073709551616)] =>
      rewrite (clip_minneg x) by lia end
  | progress rewrite ?m64_add_r, ?sw_m64_l, ?sw_m64_ls, ?sw_sw_ls, ?sw_sw_l, ?sw_m64_rs, ?sw_m64_r
  | match goal with |- context [bv_swrap 32 ?z] => lazymatch z with context [bv_swrap _ _] => fail | context [_ mod _] => fail | _ =>
      rewrite (bv_swrap_small 32 z) by (change (bv_half_modulus 32) with (2^31); lia) end end ].
Ltac clipnorm := repeat clipnorm1.

(* [comment removed for export] *)
Ltac is_store := next_instr ltac:(fun i => lazymatch i with Store _ _ _ _ => idtac end).
Ltac pwalk1 := first [ is_store; do 3 (try progress pre_norm); gwalk1 | gwalk1 ].
Ltac pwalk_step stops := first [ at_stop stops; fail 1 | pwalk1 | shfix | maskrow_auto | progress pre_norm ].
Ltac pwalk stops := repeat (pwalk_step stops).
(* [comment removed for export] *)
Ltac cb_gen H := repeat match type of H with context [CB ?n ?bs] =>
  lazymatch bs with
  | firstn _ _ => let b := fresh "cbj" in set (b := bs) in H; clearbody b
  | skipn _ _ => let b := fresh "cbj" in set (b := bs) in H; clearbody b
  end end.

(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac ropl_front_b02 :=
  unfold ropl_gen_case;
  intros ra gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m usp lo datad dpixw dpixh dwpl dx dy dw dh datas spixw spixh swpl sx sy dn sn
    DX0 DY0 DW0 DH0 DXW DYH DPW DPH SX0 SY0 SXW SYH SPW SPH DWPL SWPL DD0 DD4 DS0 DS4 DXM SXM EDN ESN DWC SWC DNHI SNHI DDHI DSHI DSH DDST DSST
    WRS ACS WRD ACD ACLM ACRM ST LOR UHI U16 LO0 ARGS MI CC;
  destruct CC as (G1 & G2 & G3 & G4); unfold g_GOT_shadow_offset_cell, g_shadow_memory_dynamic_address, g_GOT_detect_uar, g_detect_stack_use_after_return in G1, G2, G3, G4; clear G3 G4;
  pose proof (munch_refl [(usp + -256, usp); (datad, datad + dn)] m) as MU; pose proof (wmono_refl asegs m) as WM;
  assert (YD : 0 <= dwpl * dy < 2^24)
    by (split; [apply Z.mul_nonneg_nonneg; lia|]; assert (dwpl * dy <= dwpl * (dpixh - 1)) by (apply Z.mul_le_mono_nonneg_l; lia); lia);
  assert (YS : 0 <= swpl * sy < 2^24)
    by (split; [apply Z.mul_nonneg_nonneg; lia|]; assert (swpl * sy <= swpl * (spixh - 1)) by (apply Z.mul_le_mono_nonneg_l; lia); lia);
  assert (XD : 0 <= dx * 8 / 32 <= 5000) by (split; [apply Z.div_pos; lia| apply Z.div_le_upper_bound; lia]);
  assert (XS : 0 <= sx * 8 / 32 <= 5000) by (split; [apply Z.div_pos; lia| apply Z.div_le_upper_bound; lia]);
  hide WRS; hide ACS; hide WRD; hide ACD; hide DSH; hide DDST; hide DSST;
  lwalk [0xb4b2c]; clipfix;
  lwalk [0xb4ce0];
  (let L31 := fresh "L31" in
   assert (L31 : forall x, 0 <= x -> Z.land (x * 8) 31 = 8 * (x mod 4))
     by (intros x Hx; change 31 with (Z.ones 5); rewrite Z.land_ones by lia; change (2 ^ 5) with (4 * 8); rewrite Z.mul_mod_distr_r by lia; lia);
   rewrite Z.land_lor_distr_l, (L31 dx DX0), (L31 sx SX0), DXM, SXM; clear L31);
  (let dxq := fresh "dxq" in let sxq := fresh "sxq" in let EDX := fresh "EDX" in let ESX := fresh "ESX" in
   set (dxq := dx / 4) in *; set (sxq := sx / 4) in *;
   assert (EDX : dx = 4 * dxq + dx mod 4) by (unfold dxq; apply Z.div_mod; lia);
   assert (ESX : sx = 4 * sxq + sx mod 4) by (unfold sxq; apply Z.div_mod; lia);
   assert (DXQ : 0 <= dxq) by (unfold dxq; apply Z.div_pos; lia);
   assert (SXQ : 0 <= sxq) by (unfold sxq; apply Z.div_pos; lia);
   rewrite DXM in EDX; rewrite SXM in ESX; clearbody dxq sxq; subst dx sx; clear DXM SXM;
   assert (XQD : dxq <= 5000) by lia;
   assert (XQS : sxq <= 5000) by lia);
  norm_coords; gcalc;
  lwalk [0xb4d24; 0xb4b48];
  try rewrite !land31_32q by lia; try rewrite !land31_32q0 by lia; gcalc;
  lwalk [0xb4d24; 0xb4b48].
(* [comment removed for export] *)
Ltac ropl_restore :=
  unhide_all;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
  lazymatch goal with WRS : wr_at asegs ?m0 ?SR ?sn, WRD : wr_at asegs ?m0 ?DR ?dn, ACS : acc asegs ?m0 ?SR ?sn, ACD : acc asegs ?m0 ?DR ?dn,
                      MU : munch _ ?m0 mm, WM : wmono asegs ?m0 mm |- _ =>
    apply (fun h => wr_at_transport asegs m0 mm SR sn h WM) in WRS;
    apply (fun h => wr_at_transport asegs m0 mm DR dn h WM) in WRD;
    apply (fun h => acc_munch_out2 m0 mm _ _ _ _ SR sn MU ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) h) in ACS;
    apply (fun h => acc_munch_out2 m0 mm _ _ _ _ DR dn MU ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) h) in ACD
  end end.
Ltac ropl_rehide := repeat match goal with H : _ \/ _ |- _ => hide H end.
