Lemma land3_of_mod4 : forall x, x mod 4 = 0 -> Z.land x 3 = 0.
Proof.
ltac2:(KReplay.run1 (kr_t_Bi_ropl_gdef ()) [] "h02Hxh17__arithh24__ffh36__sat0h48__varmaph55__with61xh71zp;1p;2p;3p;4p;7p;6g004]j14Tg005Bj15Tg007\j22Tg008<j31Tg007?j2GTg00Akj1CTg00BIj2<Tg01GSj2;Tg004Aj20Tg0090j17Tg009Pj16Tg00:0j18Tg00:Nj19Tg00:lj1FTg00;Wj23Tg00<:j4ETg00CJj7BTg00=Ij2=Tg008Vj2>Tg00=kj2?Tg00>Wj3@Tg00?6j4ATg00Bgj3:Tg00@Ij6DTg00EmR0f0R1g00Fi#4R2#4#5R3'2g00FKR4510P0f1R5%52R2/G2'2A1014X70P1%C2,<51;5310451043f3/23,04[[g00GNR3#7%63%80%90%F0R3g00Cng00DMR6P6g00DmR6P01304g00J>1302CEg00EMFB1=36P1f2R6g00HaR3g00IAR7'>1?16=137dA@045CAb2b4b51042P1b1b39:52EDW0W6o"). Qed.
Ltac fr_norm H D4 S4 :=
  repeat match type of H with
  | context [Z.land ?p 3] => rewrite (land3_of_mod4 p) in H by (clear - D4 S4; Z.div_mod_to_equations; lia)
  | context [Z.lxor ?x 9223372036854775808 <? 9223372036854775808] => rewrite (slt0_nonneg x) in H by lia
  | context [bv_wrap 32 ?z] => rewrite (bv_wrap_small 32 z) in H by (change (bv_modulus 32) with (2^32); lia)
  | context [(32 * ?q + ?c) / 32] => rewrite (div32_32q q c) in H
  | context [bv_swrap 32 ?z] => lazymatch z with context [_ / _] => fail | _ =>
      rewrite (bv_swrap_small 32 z) in H by (change (bv_half_modulus 32) with (2^31); lia) end
  end;
  cbn [Z.b2z] in H; change (Z.b2z (0 <? 1)) with 1 in H; rewrite ?Z.add_0_r in H;
  repeat match type of H with context [?c / 32] => lazymatch isZcst c with true => let v := eval vm_compute in (c / 32) in change (c / 32) with v in H end end;
  rewrite ?Z.add_0_r in H.

