(* [comment removed for export] *)
Definition gf1f_exit (sp gp tp t1 s0 s1 a4 a6 s2 s10 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (DR dn : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t2' t3' t4' a0' a1' a2' a3' a5' a7' s3' s4' s5' s6' s7' s8' s9' s11' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1 t2' s0 s1 a0' a1' a2' a3' a4 a5' a6 a7' s2 s3' s4' s5' s6' s7' s8' s9' s10 s11' t3' t4' t5 t6)
             F (Z_to_bv 64 0xbe1bc) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.
Lemma gf1_full : forall (gp tp t0 t2 t3 t4 s0 s3 s4 s5 s6 s8 s10 s11 a0 a1 a2 a3 a4 a5 a6 s2 t5 w0 : word)
    F fc (m : mem)
    (FP dh swpl dwpl PS1 PD1 SR sn DR dn fs9 fs4 sh rsh dy dpixh sy spixh : Z),
  1 <= dh <= 20000 -> 0 <= dy -> dy + dh <= dpixh -> dpixh <= 20000 -> 0 <= sy -> sy + dh <= spixh -> spixh <= 20000 ->
  0 < swpl <= 2^24 -> 0 < dwpl <= 2^24 -> swpl * dh <= 2^24 -> dwpl * dh <= 2^24 ->
  0 < SR -> SR mod 4 = 0 -> SR + sn <= 2^47 -> 0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> PS1 mod 4 = 0 -> PD1 mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  0 < FP -> FP mod 16 = 0 -> FP + 256 <= 2^47 -> (DR + dn <= FP \/ FP + 256 <= DR) ->
  0 <= fs9 < 2 -> 0 <= fs4 < 2 -> 0 <= sh < 32 -> 0 <= rsh < 32 ->
  (forall i', 0 <= i' <= dh -> SR <= PS1 + 4 * (swpl * i') /\ PS1 + 4 * (swpl * i') + 4 <= SR + sn + 4 * swpl) ->
  (fs9 = 1 -> fs4 = 0 -> forall i', 0 <= i' < dh -> PS1 + 4 * (swpl * i') + 8 <= SR + sn) ->
  (forall i', 0 <= i' < dh -> SR <= PS1 + 4 * (swpl * i') /\ PS1 + 4 * (swpl * i') + 4 <= SR + sn) ->
  (forall i', 0 <= i' < dh -> DR <= PD1 + 4 * (dwpl * i') /\ PD1 + 4 * (dwpl * i') + 4 <= DR + dn) ->
  rw_cells asegs m FP [C8 w0] -> rw_cells asegs m (FP + 16) [C8 (Z_to_bv 64 fs4)] ->
  rw_cells asegs m (FP + 40) [C8 (Z_to_bv 64 (dy + dh - dpixh)); C8 (Z_to_bv 64 sy); C8 (Z_to_bv 64 sy); C8 (Z_to_bv 64 dpixh); C8 (Z_to_bv 64 dy);
                              C8 (Z_to_bv 64 spixh)] ->
  rw_cells asegs m (FP + 120) [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 swpl); C8 (Z_to_bv 64 dwpl)] ->
  wr_at asegs m SR sn -> acc asegs m SR sn -> wr_at asegs m DR dn -> acc asegs m DR dn -> mem_inv asegs m ->
  evt asegs (gf1f_exit (Z_to_bv 64 FP) gp tp (Z_to_bv 64 2147450880) s0 (Z_to_bv 64 rsh) a4 a6 s2 s10 t5 (Z_to_bv 64 sh) F fc m DR dn)
    (MS (mkR (Z_to_bv 64 PD1) (Z_to_bv 64 FP) gp tp t0 (Z_to_bv 64 2147450880) t2 s0 (Z_to_bv 64 rsh) a0 a1 a2 a3 a4 a5 a6 (Z_to_bv 64 0)
             s2 s3 s4 s5 s6 (Z_to_bv 64 PS1) s8 (Z_to_bv 64 fs9) s10 s11 t3 t4 t5 (Z_to_bv 64 sh))
