Ltac fr_flags H :=
  repeat match type of H with context [Z.lxor ?x 9223372036854775808] => rewrite (lxor_sign x) in H by lia end;
  repeat match type of H with
  | context [?a <? ?b] => first [ replace (a <? b) with true in H by (symmetry; apply Z.ltb_lt; lia) | replace (a <? b) with false in H by (symmetry; apply Z.ltb_ge; lia) ]
  | context [?a <=? ?b] => first [ replace (a <=? b) with true in H by (symmetry; apply Z.leb_le; lia) | replace (a <=? b) with false in H by (symmetry; apply Z.leb_gt; lia) ]
  | context [?a =? ?b] => first [ replace (a =? b) with true in H by (symmetry; apply Z.eqb_eq; lia) | replace (a =? b) with false in H by (symmetry; apply Z.eqb_neq; lia) ]
  end; gnorm_in H.

Ltac ropl_pre2 := pw6 [0xb9a4c; 0xb4ed0; 0xb5408; 0xb55a8];
  first [ at_pc 0xb9a4c | lwalk1; first [ xbrT8 | xbrF8 | ropl_fork ]; ropl_pre2 ].
