Ltac frame_fact k := lazymatch goal with FR : rw_cells _ _ (_ + -256) _ |- _ => k FR end.

Ltac cells_index cs off :=
  let rec go k := lazymatch k with
    | 40%nat => fail 1 "cells_index: offset not found" off
    | _ => let v := eval vm_compute in (Z.of_nat (cells_size (firstn k cs))) in
           lazymatch v with
           | off => k
           | _ => go (S k)
           end
    end in go O.

Ltac sub_at FR off n NAME :=
  lazymatch type of FR with rw_cells _ _ _ ?cs =>
    let k := cells_index cs off in
    pose proof (rw_cells_sub _ _ _ k n FR) as NAME; cbn [firstn skipn cells_size csize] in NAME; fix_ofnat NAME
  end.

Ltac ph_norm2 DD4 DS4 := frame_fact ltac:(fun FR => cb_gen FR; fr_norm FR DD4 DS4; fr_flags FR; rewrite ?Z.sub_0_r, ?Z.add_0_r in FR); rewrite ?Z.sub_0_r, ?Z.add_0_r.

Ltac gphase_after2 m1 m' MU' WM' DSH DDST LOR :=
  let OUT := fresh "OUT" in
  lazymatch type of MU' with munch [(?D, ?D + ?dn)] m1 m' =>
    assert (OUT : D + dn <= 0x7fff8000 \/ 0x10007fff8000 <= D) by (unfold hid in DSH; clear - DSH; lia);
    rop_transport m1 m' MU' WM' OUT; clear OUT;
    repeat match goal with
    | H : rw_cells asegs m1 ?A ?cs |- _ =>
        first [ apply (rw_cells_agree_nw asegs m1 m' A cs) in H;
                [| apply (agree_of_munch _ _ _ _ MU'); intros x Hx; cbn [outside]; split; [| exact I];
                   lazymatch type of Hx with context [Z.of_nat ?n] => let v := eval vm_compute in (Z.of_nat n) in change (Z.of_nat n) with v in Hx end;
                   first [ (unfold hid in DDST; clear - Hx DDST LOR; lia) | lia ] ]
              | clear H ]
    | H : stk asegs m1 ?l ?h |- _ => apply (stk_agree_nw asegs m1 m' l h) in H;
        [| apply (agree_of_munch _ _ _ _ MU'); intros x Hx; cbn [outside]; split; [| exact I];
           first [ (unfold hid in DDST; clear - Hx DDST LOR; lia) | lia ] ]
    | H : ro_cells asegs m1 _ _ |- _ => clear H
    | H : acc asegs m1 _ _ |- _ => clear H
    | H : mem_inv asegs m1 |- _ => clear H
    end;
    lazymatch goal with MU : munch ?W ?m0 m1, WM : wmono asegs ?m0 m1 |- _ =>
      let MU2 := fresh "MU" in let WM2 := fresh "WM" in
      assert (MU2 : munch W m0 m') by (apply (munch_trans _ _ _ _ MU); intros x Hx; apply MU'; cbn [outside] in *; tauto);
      pose proof (wmono_trans _ _ _ _ WM WM') as WM2; clear MU WM MU' WM'; try clear m1 end
  end.

Ltac gphase_post2 DSH DDST LOR := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
  lazymatch goal with MU' : munch _ ?m1 mm, WM' : wmono asegs ?m1' mm |- _ => gphase_after2 m1 mm MU' WM' DSH DDST LOR end end.

Ltac ph1_apply6 vSR vsn vDR vdn vswpl vdwpl vsy vdy vsph vdph vdh DS4 DD4 DDST LOR DSH :=
  ph_norm2 DD4 DS4; gnorm;
  reg_val (Z_to_bv 5 23) ltac:(fun vs7 => reg_val (Z_to_bv 5 1) ltac:(fun vra =>
  lazymatch vs7 with Z_to_bv 64 ?vPS => lazymatch vra with Z_to_bv 64 ?vPD =>
  frame_fact ltac:(fun FR =>
  let FR0 := fresh "FR0" in let FC16 := fresh "FC16" in let FC40 := fresh "FC40" in let FC120 := fresh "FC120" in
  sub_at FR 0 1%nat FR0; sub_at FR 16 1%nat FC16; sub_at FR 40 6%nat FC40; sub_at FR 120 4%nat FC120; rewrite ?Z.add_0_r in FR0;
  lazymatch type of FC16 with rw_cells _ _ _ [C8 (Z_to_bv 64 ?vfs4)] =>
  let PS4 := fresh "PS4" in let PD4 := fresh "PD4" in
  let SDH := fresh "SDH" in let DDH := fresh "DDH" in let RS := fresh "RS" in let RSN := fresh "RSN" in let RS2 := fresh "RS2" in let RD := fresh "RD" in
  assert (PS4 : vPS mod 4 = 0) by (clear - DS4; Z.div_mod_to_equations; lia);
  assert (PD4 : vPD mod 4 = 0) by (clear - DD4; Z.div_mod_to_equations; lia);
  assert (SDH : vswpl * vdh <= 2^24) by (assert (vswpl * vdh <= vswpl * vsph) by (apply Z.mul_le_mono_nonneg_l; lia); lia);
  assert (DDH : vdwpl * vdh <= 2^24) by (assert (vdwpl * vdh <= vdwpl * vdph) by (apply Z.mul_le_mono_nonneg_l; lia); lia);
  assert (RS : forall i', 0 <= i' < vdh -> vSR <= vPS + 4 * (vswpl * i') /\ vPS + 4 * (vswpl * i') + 4 <= vSR + vsn)
    by (apply (rows_fit' vSR vsn vPS vswpl vdh 4 vsy vsph); lia);
  assert (RSN : forall i', 0 <= i' <= vdh -> vSR <= vPS + 4 * (vswpl * i') /\ vPS + 4 * (vswpl * i') + 4 <= vSR + vsn + 4 * vswpl)
    by (intros i' Hi'; assert (vswpl * (vsy + i') <= vswpl * vsph) by (apply Z.mul_le_mono_nonneg_l; lia); assert (0 <= vswpl * i') by (apply Z.mul_nonneg_nonneg; lia);
        assert (0 <= vswpl * vsy) by (apply Z.mul_nonneg_nonneg; lia); lia);
  assert (RS2 : forall fs9, fs9 = 1 -> vfs4 = 0 -> forall i', 0 <= i' < vdh -> vPS + 4 * (vswpl * i') + 8 <= vSR + vsn)
    by (intros fs9' E9 E4; first [ exfalso; clear - E4; lia | intros i' Hi'; apply (proj2 ((rows_fit' vSR vsn vPS vswpl vdh 8 vsy vsph ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) i' Hi')) ]);
  assert (RD : forall i', 0 <= i' < vdh -> vDR <= vPD + 4 * (vdwpl * i') /\ vPD + 4 * (vdwpl * i') + 4 <= vDR + vdn)
    by (apply (rows_fit' vDR vdn vPD vdwpl vdh 4 vdy vdph); lia);
  eapply evt_cut; [ eapply gf1_full with (SR := vSR) (sn := vsn) (DR := vDR) (dn := vdn) (PS1 := vPS) (PD1 := vPD) (fs4 := vfs4)
                               (dh := vdh) (swpl := vswpl) (dwpl := vdwpl) (dy := vdy) (dpixh := vdph) (sy := vsy) (spixh := vsph);
      first [exact FR0 | exact FC16 | exact FC40 | exact FC120 | exact RS | exact RSN | exact (RS2 _) | exact RD | exact SDH | exact DDH
            | assumption | (unfold hid in DSH; exact DSH) | reflexivity | lia | (unfold hid in DDST; clear - DDST LOR; lia) | (unfold hid in *; lia) ] | ];
  cbv beta; intros ?ms' (?f_ra & ?f_t0 & ?f_t2 & ?f_t3 & ?f_t4 & ?f_a0 & ?f_a1 & ?f_a2 & ?f_a3 & ?f_a5 & ?f_a7 & ?f_s3 & ?f_s4 & ?f_s5 & ?f_s6 & ?f_s7 & ?f_s8 & ?f_s9 & ?f_s11 & ?mf & -> & ?MU' & ?WM' & ?MIf);
  gphase_post2 DSH DDST LOR; try clear FR0; try clear FC16; try clear FC40; try clear FC120; try clear RS; try clear RSN; try clear RS2; try clear RD; try clear SDH; try clear DDH; try clear PS4; try clear PD4; ropl_rehide
  end) end end)).

Ltac ph2_apply6 vSR vsn vDR vdn vswpl vdwpl vsy vdy vsph vdph vdh DS4 DD4 DDST LOR DSH :=
  ph_norm2 DD4 DS4;
  reg_val (Z_to_bv 5 16) ltac:(fun va6 => reg_val (Z_to_bv 5 14) ltac:(fun va4 => reg_val (Z_to_bv 5 28) ltac:(fun vt3 =>
  lazymatch va6 with Z_to_bv 64 ?vPS => lazymatch va4 with Z_to_bv 64 ?vPD => lazymatch vt3 with Z_to_bv 64 (?vnf * 4) =>
  frame_fact ltac:(fun FR =>
  let FC16 := fresh "FC16" in let FC96 := fresh "FC96" in let PS4 := fresh "PS4" in let PD4 := fresh "PD4" in
  let SDH := fresh "SDH" in let DDH := fresh "DDH" in let RS := fresh "RS" in let RD := fresh "RD" in let GW := fresh "GW" in
  sub_at FR 16 3%nat FC16; sub_at FR 96 5%nat FC96;
  assert (PS4 : vPS mod 4 = 0) by (clear - DS4; Z.div_mod_to_equations; lia);
  assert (PD4 : vPD mod 4 = 0) by (clear - DD4; Z.div_mod_to_equations; lia);
  assert (SDH : vswpl * vdh <= 2^24) by (assert (vswpl * vdh <= vswpl * vsph) by (apply Z.mul_le_mono_nonneg_l; lia); lia);
  assert (DDH : vdwpl * vdh <= 2^24) by (assert (vdwpl * vdh <= vdwpl * vdph) by (apply Z.mul_le_mono_nonneg_l; lia); lia);
  assert (RS : forall i', 0 <= i' < vdh -> vSR <= vPS + 4 * (vswpl * i') /\ vPS + 4 * (vswpl * i') + 4 * (vnf + 1) <= vSR + vsn)
    by (apply (rows_fit' vSR vsn vPS vswpl vdh (4 * (vnf + 1)) vsy vsph); lia);
  assert (RD : forall i', 0 <= i' < vdh -> vDR <= vPD + 4 * (vdwpl * i') /\ vPD + 4 * (vdwpl * i') + 4 * vnf <= vDR + vdn)
    by (apply (rows_fit' vDR vdn vPD vdwpl vdh (4 * vnf) vdy vdph); lia);
  pose proof (gw2_rows (Z.to_nat vdh) 0) as GW;
  setoid_rewrite Z.mul_0_r in GW; setoid_rewrite Z.mul_0_r in GW; setoid_rewrite Z.add_0_r in GW;
  eapply evt_cut; [ eapply GW with (SR := vSR) (sn := vsn) (DR := vDR) (dn := vdn) (PSF := vPS) (PDF := vPD) (dh := vdh) (n := vnf)
                               (swpl := vswpl) (dwpl := vdwpl);
      first [exact FC16 | exact FC96 | exact RS | exact RD | exact SDH | exact DDH | assumption | (unfold hid in DSH; exact DSH) | reflexivity | lia
            | (unfold hid in DDST; clear - DDST LOR; lia) | (unfold hid in *; lia) ] | ];
  cbv beta; intros ?ms' (?w_ra & ?w_t2 & ?w_a0 & ?w_a1 & ?w_a2 & ?w_a4 & ?w_a5 & ?w_a6 & ?w_s3 & ?w_s4 & ?w_s5 & ?w_s7 & ?w_s8 & ?w_s9 & ?w_s11 & ?mw & -> & ?MU' & ?WM' & ?MIw);
  gphase_post2 DSH DDST LOR; try clear RS; try clear RD; try clear FC16; try clear FC96; try clear GW; try clear SDH; try clear DDH; try clear PS4; try clear PD4; ropl_rehide)
  end end end))).

Ltac ph3_apply6 vSR vsn vDR vdn vswpl vdwpl vsy vdy vsph vdph vdh DS4 DD4 DDST LOR DSH :=
  ph_norm2 DD4 DS4;
  reg_val (Z_to_bv 5 18) ltac:(fun vs2 => lazymatch vs2 with Z_to_bv 64 ?vPD =>
  frame_fact ltac:(fun FR =>
  let FC8 := fresh "FC8" in let FC24 := fresh "FC24" in let FC40 := fresh "FC40" in let FC120 := fresh "FC120" in
  sub_at FR 8 1%nat FC8; sub_at FR 24 1%nat FC24; sub_at FR 40 9%nat FC40; sub_at FR 120 4%nat FC120;
  lazymatch type of FC8 with rw_cells _ _ _ [C8 (Z_to_bv 64 ?vfl)] =>
  lazymatch type of FC40 with rw_cells _ _ _ [_; _; _; _; _; _; _; _; C8 (Z_to_bv 64 ?vPS)] =>
  let PS4 := fresh "PS4" in let PD4 := fresh "PD4" in
  let SDH := fresh "SDH" in let DDH := fresh "DDH" in let RS := fresh "RS" in let RSN := fresh "RSN" in let RS2 := fresh "RS2" in let RD := fresh "RD" in
  assert (PS4 : vPS mod 4 = 0) by (clear - DS4; Z.div_mod_to_equations; lia);
  assert (PD4 : vPD mod 4 = 0) by (clear - DD4; Z.div_mod_to_equations; lia);
  assert (SDH : vswpl * vdh <= 2^24) by (assert (vswpl * vdh <= vswpl * vsph) by (apply Z.mul_le_mono_nonneg_l; lia); lia);
  assert (DDH : vdwpl * vdh <= 2^24) by (assert (vdwpl * vdh <= vdwpl * vdph) by (apply Z.mul_le_mono_nonneg_l; lia); lia);
  assert (RS : forall i', 0 <= i' < vdh -> vSR <= vPS + 4 * (vswpl * i') /\ vPS + 4 * (vswpl * i') + 4 <= vSR + vsn)
    by (apply (rows_fit' vSR vsn vPS vswpl vdh 4 vsy vsph); lia);
  assert (RSN : forall i', 0 <= i' <= vdh -> vSR <= vPS + 4 * (vswpl * i') /\ vPS + 4 * (vswpl * i') + 4 <= vSR + vsn + 4 * vswpl)
    by (intros i' Hi'; assert (vswpl * (vsy + i') <= vswpl * vsph) by (apply Z.mul_le_mono_nonneg_l; lia); assert (0 <= vswpl * i') by (apply Z.mul_nonneg_nonneg; lia);
        assert (0 <= vswpl * vsy) by (apply Z.mul_nonneg_nonneg; lia); lia);
  assert (RS2 : vfl = 0 -> forall i', 0 <= i' < vdh -> vPS + 4 * (vswpl * i') + 8 <= vSR + vsn)
    by (first [ intros E; exfalso; clear - E; lia | intros _; intros i' Hi'; apply (proj2 ((rows_fit' vSR vsn vPS vswpl vdh 8 vsy vsph ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) i' Hi')) ]);
  assert (RD : forall i', 0 <= i' < vdh -> vDR <= vPD + 4 * (vdwpl * i') /\ vPD + 4 * (vdwpl * i') + 4 <= vDR + vdn)
    by (apply (rows_fit' vDR vdn vPD vdwpl vdh 4 vdy vdph); lia);
  eapply evt_cut; [ eapply gl3_full with (SR := vSR) (sn := vsn) (DR := vDR) (dn := vdn) (PS3 := vPS) (PD3 := vPD) (fl := vfl)
                               (dh := vdh) (swpl := vswpl) (dwpl := vdwpl) (dy := vdy) (dpixh := vdph) (sy := vsy) (spixh := vsph);
