            | assumption | (unfold hid in DSH; exact DSH) | reflexivity | lia | (unfold hid in DDST; clear - DDST LOR; lia) | (unfold hid in *; lia) ] | ];
  cbv beta; intros ?ms' (?l_t0 & ?l_t2 & ?l_t3 & ?l_t4 & ?l_s2 & ?l_s3 & ?l_s4 & ?l_s5 & ?l_s6 & ?l_s7 & ?l_s8 & ?l_a0 & ?l_a1 & ?l_a2 & ?l_a3 & ?l_a4 & ?l_a5 & ?l_a6 & ?l_a7 & ?ml & -> & ?MU' & ?WM' & ?MIl);
  gphase_post2 DSH DDST LOR; try clear FC8; try clear FC24; try clear FC40; try clear FC120; try clear RS; try clear RSN; try clear RS2; try clear RD; try clear SDH; try clear DDH; try clear PS4; try clear PD4; ropl_rehide
  end end) end).

Ltac ropl_finish :=
  lwalk (@nil Z);
  apply evt_done; unfold ropl_exit; do 15 eexists;
  lazymatch goal with |- exists m', MS _ _ _ _ _ ?mm _ = _ /\ _ => exists mm end;
  split; [reflexivity|];
  lazymatch goal with MU : munch _ _ ?mm, WM : wmono asegs _ ?mm', ST : stk asegs _ _ _ |- _ =>
    split; [exact MU|]; split; [exact WM|]; split; [| exact ST]; lazymatch goal with H : mem_inv asegs mm |- _ => exact H end end.

Ltac last_flag k := frame_fact ltac:(fun FR => let F24 := fresh "F24" in sub_at FR 24 1%nat F24;
  lazymatch type of F24 with rw_cells _ _ _ [C8 ?w] => clear F24; k w end).
Ltac cell_split off := frame_fact ltac:(fun FR => let C := fresh "CS" in sub_at FR off 1%nat C;
   lazymatch type of C with rw_cells _ _ _ [C8 (Z_to_bv 64 ?v)] => clear C;
     lazymatch v with context [?a <? ?b] => destruct (Z_lt_le_dec a b); frame_fact ltac:(fun FR' => fr_flags FR') | _ => idtac end end).
Ltac ropl_arm vSR vsn vDR vdn vswpl vdwpl vsy vdy vsph vdph vdh DS4 DD4 DDST LOR DSH :=
  ropl_restore; ropl_rehide; ph_norm2 DD4 DS4; unfold SHB;
  pw6 [0xb9a60; 0xbe414];
  (first [ at_pc 0xb9a60; cell_split 16; ph1_apply6 vSR vsn vDR vdn vswpl vdwpl vsy vdy vsph vdph vdh DS4 DD4 DDST LOR DSH | idtac ]);
  pw6 [0xbe468; 0xbe5c4];
  (first [ at_pc 0xbe468; ph2_apply6 vSR vsn vDR vdn vswpl vdwpl vsy vdy vsph vdph vdh DS4 DD4 DDST LOR DSH | idtac ]);
  ph_norm2 DD4 DS4;
  last_flag ltac:(fun w => lazymatch w with
    | Z_to_bv 64 0 => cell_split 8; ph3_apply6 vSR vsn vDR vdn vswpl vdwpl vsy vdy vsph vdph vdh DS4 DD4 DDST LOR DSH
    | _ => pw6 [0xbe930] end);
  ropl_finish.
